        {
            "id": raw_id,
            "digest": status.digest,
            "total_chunks": status.total,
            "received_chunks": status.received_chunks,
            "missing_chunks": list(status.missing_chunks),
            "complete": status.complete,
            "size": status.size,
        },
        trailing_newline=True,
